u = ImplicitPDESoln(f,alpha,beta,tEnd,dx,gamma,L); %[output:66fe58fa]
%[text] Plot the initial value `u0` and the final value `u` on the same plot.
plot(0:dx:L,f(0:dx:L),"LineWidth",4) %[output:62d60903]
hold on %[output:62d60903]
plot(0:dx:L,[alpha(tEnd);u;beta(tEnd)],"LineWidth",4) %[output:62d60903]
hold off %[output:62d60903]
title("Solving $\frac{\partial u}{\partial t} = \gamma \frac{\partial^2 u}{\partial x^2}$","Interpreter","latex") %[output:62d60903]
subtitle("$t=$"+tEnd,"Interpreter","latex") %[output:62d60903]
xlabel("$x$","Interpreter","latex") %[output:62d60903]
ylabel("$u$","Interpreter","latex") %[output:62d60903]
legend(["u(0,x)","u(t,x)"],"Location","north") %[output:62d60903]
